  phases,
  unknown,
  ;
}

/// A read-only workflow task. The optional phase handle is opaque and scoped
/// to the Client and complete phase-list generation that produced it.
class ServiceHallWorkflowTaskDto {
  final String title;
  final String status;
  final String step;
  final String applicationTime;
  final int? progressPercent;
  final String? phaseReferenceId;

  const ServiceHallWorkflowTaskDto({
    required this.title,
    required this.status,
    required this.step,
    required this.applicationTime,
    this.progressPercent,
    this.phaseReferenceId,
  });

  @override
  int get hashCode =>
      title.hashCode ^
      status.hashCode ^
      step.hashCode ^
      applicationTime.hashCode ^
      progressPercent.hashCode ^
      phaseReferenceId.hashCode;

  @override
  bool operator ==(Object other) =>
      identical(this, other) ||
      other is ServiceHallWorkflowTaskDto &&
          runtimeType == other.runtimeType &&
          title == other.title &&
          status == other.status &&
          step == other.step &&
          applicationTime == other.applicationTime &&
          progressPercent == other.progressPercent &&
          phaseReferenceId == other.phaseReferenceId;
}
